'?></b><small><?php if($isOfficial):?>ZYNKO carga este código automáticamente en <strong><?=htmlspecialchars($i['domain'])?></strong>. Se muestra aquí para que puedas verificarlo; no necesitas pegarlo manualmente en el propio ZYNKO.<?php else:?>Úsalo solamente en <strong><?=htmlspecialchars($i['domain'])?></strong>. Las variantes con o sin <strong>www</strong> se consideran el mismo sitio; otro dominio será bloqueado.<?php endif?></small></div><code id="embedCode<?=$i['id']?>"><?=htmlspecialchars($installSnippet)?></code><button type="button" class="secondary-action" data-copy-target="embedCode<?=$i['id']?>" data-copy-message="Código único de <?=htmlspecialchars($i['domain'],ENT_QUOTES,'UTF-8')?> copiado."><i class="fa-regular fa-copy"></i> Copiar código</button></div><?php endif?></div><?php endforeach?></div><?php endif?></section><div class="modal-shell" id="installationEditModal"><div class="modal-card webchat-install-edit-modal"><div class="modal-head"><div><b>Editar sitio autorizado</b><small>Asigna un nombre claro para reconocer dónde está instalado NIVO Web Chat.</small></div><button type="button" class="modal-close"><i class="fa-solid fa-xmark"></i></button></div><form id="installationEditForm"><input type="hidden" name="action" value="webchat_installation_update"><input type="hidden" name="installation_id" value=""><div class="settings-grid"><div class="field"><label>Nombre / etiqueta</label><input name="label" maxlength="120" placeholder="Ej. Sitio corporativo"></div><div class="field"><label>Dominio autorizado</label><input name="domain" maxlength="190" required placeholder="www.cliente.com"></div></div><div class="webchat-install-help"><i class="fa-solid fa-circle-info"></i><span id="installationEditHelp">La etiqueta es solo para identificar el sitio dentro de ZYNKO. El dominio es el que autoriza técnicamente el widget.</span></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary"><i class="fa-solid fa-floppy-disk"></i> Guardar cambios</button></div></form></div></div>
</div><script>document.addEventListener('DOMContentLoaded',()=>{const launcherEditor=document.getElementById('launcherLabelEditor'),launcherInput=document.getElementById('launcherLabelInput'),launcherLive=document.getElementById('launcherLabelLive'),launcherBold=document.getElementById('launcherBoldButton'),launcherItalic=document.getElementById('launcherItalicButton'),launcherClear=document.getElementById('launcherClearButton');const launcherPlain=()=>String(launcherEditor?.innerText||'').replace(/\u00a0/g,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();const launcherTokenize=node=>{let out='';node?.childNodes?.forEach(child=>{if(child.nodeType===Node.TEXT_NODE){out+=child.textContent||'';return}if(child.nodeType!==Node.ELEMENT_NODE)return;if(child.tagName==='BR'){out+='\n';return}const block=['DIV','P'].includes(child.tagName);const inner=launcherTokenize(child);if(['STRONG','B'].includes(child.tagName))out+='**'+inner+'**';else if(['EM','I'].includes(child.tagName))out+='__'+inner+'__';else out+=inner;if(block&&!out.endsWith('\n'))out+='\n'});return out};const launcherMarkup=token=>{const esc=v=>String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));let html=esc(token);html=html.replace(/\*\*(.+?)\*\*/gs,'<strong>$1</strong>').replace(/__(.+?)__/gs,'<em>$1</em>').replace(/\n/g,'<br>');return html};const launcherPreviewRender=()=>{if(launcherLive)launcherLive.innerHTML=launcherMarkup(launcherInput?.value||'')};const launcherNormalize=()=>{if(!launcherEditor)return;const plain=launcherPlain();const lines=plain.split(/\n/).slice(0,2);let visible=lines.join('\n');if(visible.length>120){visible=visible.slice(0,120);launcherEditor.textContent=visible;showNotify('warning','Texto ajustado','El texto junto al botón admite hasta 120 caracteres visibles.')}const rawLines=(launcherEditor.innerText||'').split(/\r?\n/);if(rawLines.length>2){launcherEditor.innerHTML='';visible.split(/\n/).forEach((line,i)=>{if(i)launcherEditor.appendChild(document.createElement('br'));launcherEditor.appendChild(document.createTextNode(line))});showNotify('warning','Máximo 2 líneas','El texto flotante admite hasta dos líneas para conservar el diseño.')}};const launcherSync=()=>{if(!launcherEditor||!launcherInput)return;launcherNormalize();let token=launcherTokenize(launcherEditor).replace(/[ \t]+/g,' ').replace(/ *\n */g,'\n').replace(/\n{3,}/g,'\n\n').trim();if(token.length>240){launcherEditor.textContent=launcherPlain().slice(0,120);token=launcherEditor.textContent.trim()}launcherInput.value=token;launcherPreviewRender()};const runLauncherCmd=cmd=>{launcherEditor?.focus();document.execCommand(cmd,false,null);launcherSync()};if(launcherEditor&&launcherInput){launcherPreviewRender();launcherEditor.addEventListener('input',launcherSync);launcherEditor.addEventListener('paste',e=>{e.preventDefault();const text=(e.clipboardData||window.clipboardData).getData('text/plain').replace(/\r/g,'').split('\n').slice(0,2).join('\n');document.execCommand('insertText',false,text);launcherSync()});launcherEditor.addEventListener('keydown',e=>{if(e.key==='Enter'&&(launcherEditor.innerText||'').split(/\n/).length>=2){e.preventDefault();showNotify('warning','Máximo 2 líneas','El texto flotante admite hasta dos líneas.')}});launcherBold?.addEventListener('mousedown',e=>{e.preventDefault();runLauncherCmd('bold')});launcherItalic?.addEventListener('mousedown',e=>{e.preventDefault();runLauncherCmd('italic')});launcherClear?.addEventListener('mousedown',e=>{e.preventDefault();runLauncherCmd('removeFormat')});document.getElementById('webchatWidgetForm')?.addEventListener('submit',launcherSync,true)};const zRail=document.querySelector('.nivo-webchat-page .nivo-webchat-rail'),zConfig=document.querySelector('.nivo-webchat-page .webchat-layout>.panel');const syncRailHeight=()=>{if(!zRail||!zConfig)return;if(window.matchMedia('(min-width:1181px)').matches){zRail.style.height=zConfig.offsetHeight+'px'}else{zRail.style.height=''}};syncRailHeight();window.addEventListener('resize',syncRailHeight,{passive:true});if(window.ResizeObserver&&zConfig)new ResizeObserver(syncRailHeight).observe(zConfig);const qrEditor=document.getElementById('quickReplyEditor'),qrSource=document.getElementById('quickReplyHtmlSource'),qrShell=qrEditor?.closest('.webchat-quick-rte'),qrInput=document.getElementById('quickRepliesInput'),qrCount=document.getElementById('quickReplyCount'),qrChars=document.getElementById('quickReplyChars');const qrLines=()=>{if(!qrEditor)return[];return (qrEditor.innerText||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).slice(0,8)};const qrSync=()=>{if(!qrEditor||!qrInput)return;const lines=qrLines();qrInput.value=lines.join('\n').slice(0,650);if(qrSource&&!qrShell?.classList.contains('source-mode'))qrSource.value=qrEditor.innerHTML;if(qrCount)qrCount.textContent=String(lines.length);if(qrChars)qrChars.textContent=new Intl.NumberFormat('es-HN').format(qrInput.value.length)+' caracteres'};const qrRender=lines=>{if(!qrEditor)return;qrEditor.innerHTML='';(lines.length?lines:['']).forEach(line=>{const d=document.createElement('div');d.textContent=line;qrEditor.appendChild(d)});qrSync()};if(qrEditor&&qrInput){qrRender((qrInput.value||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).slice(0,8));qrEditor.addEventListener('input',()=>{const all=(qrEditor.innerText||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(all.length>8){qrRender(all.slice(0,8));showNotify('warning','Máximo 8 respuestas','Puedes configurar hasta 8 respuestas rápidas.');return}qrSync()});qrEditor.addEventListener('keydown',e=>{if(e.key==='Enter'&&qrLines().length>=8){e.preventDefault();showNotify('warning','Máximo 8 respuestas','Elimina una opción antes de agregar otra.')}});document.querySelectorAll('[data-quick-cmd]').forEach(b=>b.addEventListener('click',()=>{qrEditor.focus();document.execCommand(b.dataset.quickCmd,false,null);qrSync()}));document.querySelectorAll('[data-quick-align]').forEach(b=>b.addEventListener('click',()=>{qrEditor.focus();const cmd={left:'justifyLeft',center:'justifyCenter',justify:'justifyFull'}[b.dataset.quickAlign];if(cmd)document.execCommand(cmd,false,null);qrSync()}));document.getElementById('quickReplyBlockFormat')?.addEventListener('change',e=>{qrEditor.focus();document.execCommand('formatBlock',false,e.target.value==='h4'?'H4':'DIV');qrSync()});document.getElementById('quickReplyLink')?.addEventListener('click',async()=>{const ask=await Swal.fire({title:'Agregar enlace',input:'url',inputPlaceholder:'https://ejemplo.com',showCancelButton:true,confirmButtonText:'Agregar',cancelButtonText:'Cancelar',allowOutsideClick:false});if(ask.isConfirmed&&ask.value){qrEditor.focus();document.execCommand('createLink',false,ask.value);qrSync()}});document.getElementById('quickReplySource')?.addEventListener('click',()=>{const sourceMode=qrShell?.classList.toggle('source-mode');if(sourceMode){qrSource.value=qrEditor.innerHTML;qrSource.focus()}else{qrEditor.innerHTML=qrSource.value;qrSync();qrEditor.focus()}});qrSource?.addEventListener('input',()=>{const tmp=document.createElement('div');tmp.innerHTML=qrSource.value;const lines=(tmp.innerText||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).slice(0,8);qrInput.value=lines.join('\n').slice(0,650);if(qrCount)qrCount.textContent=String(lines.length);if(qrChars)qrChars.textContent=new Intl.NumberFormat('es-HN').format(qrInput.value.length)+' caracteres'});document.getElementById('webchatWidgetForm')?.addEventListener('submit',()=>{if(qrShell?.classList.contains('source-mode')){qrEditor.innerHTML=qrSource.value;qrShell.classList.remove('source-mode')}qrSync()},true)};document.querySelectorAll('.webchat-kpi b').forEach(el=>{const end=parseInt(el.textContent,10);if(!Number.isFinite(end)||end<=0)return;const start=performance.now(),duration=520;const tick=now=>{const p=Math.min(1,(now-start)/duration);el.textContent=Math.round(end*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)});const post=async fd=>{const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1','Accept':'application/json'},credentials:'same-origin',body:fd});const contentType=(r.headers.get('content-type')||'').toLowerCase();if(!contentType.includes('application/json')){if(r.status===401||r.redirected){showNotify('info','Sesión vencida','Tu sesión venció por seguridad. Inicia sesión nuevamente.');setTimeout(()=>location.href='?page=login&session_expired=1',700);throw new Error('La sesión venció.');}const raw=await r.text();throw new Error(raw.trim().startsWith('<!DOCTYPE')||raw.trim().startsWith('<html')?'El servidor devolvió una página HTML en lugar de JSON. Recarga la pantalla e intenta nuevamente.':'El servidor devolvió una respuesta no válida.');}const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.message||'No se pudo completar la acción.');return j};const bind=(id)=>{const f=document.getElementById(id);if(f)f.addEventListener('submit',async e=>{e.preventDefault();try{await post(new FormData(f));showNotify('success','Guardado','Configuración actualizada.');setTimeout(()=>location.reload(),500)}catch(x){showNotify('error','No se pudo guardar',x.message)}})};bind('webchatWidgetForm');const previewForm=document.getElementById('webchatPreviewImageForm');const previewModal=document.getElementById('webchatPreviewModal');const previewManage=document.getElementById('webchatPreviewManage');const previewZone=document.getElementById('webchatPreviewDropzone');const previewInput=previewForm?.querySelector('input[type=file]');const previewSelect=previewForm?.querySelector('.webchat-preview-select');const previewBox=document.getElementById('webchatPreviewFilePreview');const previewReset=document.getElementById('webchatPreviewReset');const previewUseGenerated=document.getElementById('webchatPreviewUseGenerated');const previewState={blobUrl:null};const escapeHtml=v=>String(v||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));const updatePreviewBox=(url,title,detail)=>{if(!previewBox)return;previewBox.hidden=false;previewBox.innerHTML=`<img src="${url}" alt="Vista previa seleccionada"><div><b>${escapeHtml(title)}</b><small>${escapeHtml(detail)}</small></div>`};const setPreviewFile=file=>{if(!file)return;if(!/^image\/(jpeg|png|webp)$/i.test(file.type)){showNotify('warning','Archivo no válido','Selecciona una imagen JPG, PNG o WEBP.');return;}if(file.size>12*1024*1024){showNotify('warning','Imagen demasiado grande','La captura admite hasta 12 MB.');return;}if(previewInput){const dt=new DataTransfer();dt.items.add(file);previewInput.files=dt.files;}if(previewState.blobUrl)URL.revokeObjectURL(previewState.blobUrl);previewState.blobUrl=URL.createObjectURL(file);updatePreviewBox(previewState.blobUrl,file.name||'captura-preview',`${Math.max(1,Math.round(file.size/1024))} KB · lista para guardar`)};previewManage?.addEventListener('click',()=>window.ZynkoModal?.open('#webchatPreviewModal'));if(previewForm&&previewZone&&previewInput){previewSelect?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();previewInput.click()});previewZone.addEventListener('click',e=>{if(!e.target.closest('button'))previewInput.click()});previewZone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();previewInput.click()}});previewInput.addEventListener('change',()=>setPreviewFile(previewInput.files?.[0]));['dragenter','dragover'].forEach(ev=>previewZone.addEventListener(ev,e=>{e.preventDefault();previewZone.classList.add('is-drag')}));['dragleave','drop'].forEach(ev=>previewZone.addEventListener(ev,e=>{e.preventDefault();previewZone.classList.remove('is-drag')}));previewZone.addEventListener('drop',e=>setPreviewFile(e.dataTransfer?.files?.[0]));document.addEventListener('paste',e=>{if(!previewModal?.classList.contains('open')&&previewModal?.getAttribute('aria-hidden')!=='false')return;const items=[...(e.clipboardData?.items||[])];const img=items.find(i=>/^image\//i.test(i.type||''));if(!img)return;e.preventDefault();setPreviewFile(img.getAsFile())});previewForm.addEventListener('submit',async e=>{e.preventDefault();if(!previewInput.files?.length){showNotify('warning','Falta la captura','Selecciona una imagen antes de guardar.');return;}const btn=previewForm.querySelector('button[type=submit]');const old=btn.innerHTML;btn.disabled=true;btn.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Guardando…';try{await post(new FormData(previewForm));showNotify('success','Preview actualizado','La captura quedó guardada y activa.');setTimeout(()=>location.reload(),400)}catch(x){showNotify('error','No se pudo guardar',x.message)}finally{btn.disabled=false;btn.innerHTML=old}});previewReset?.addEventListener('click',async()=>{if(previewReset.disabled)return;const ask=await Swal.fire({title:'Eliminar captura personalizada',text:'Se eliminará la imagen guardada y el preview seguirá usando el modo limpio generado por ZYNKO.',icon:'question',showCancelButton:true,confirmButtonText:'Sí, eliminar',cancelButtonText:'Cancelar',allowOutsideClick:false});if(!ask.isConfirmed)return;const fd=new FormData();fd.append('action','webchat_preview_reset');try{await post(fd);showNotify('success','Captura eliminada','El preview quedó en modo limpio generado.');setTimeout(()=>location.reload(),350)}catch(x){showNotify('error','No se pudo eliminar',x.message)}});previewUseGenerated?.addEventListener('click',async()=>{const fd=new FormData();fd.append('action','webchat_preview_mode');fd.append('mode','generated');try{await post(fd);showNotify('success','Preview limpio activado','La vista previa volvió al modo limpio sin fondo del sitio.');setTimeout(()=>location.reload(),350)}catch(x){showNotify('error','No se pudo cambiar',x.message)}});}bind('installationForm');const editModal=document.getElementById('installationEditModal'),editForm=document.getElementById('installationEditForm');document.querySelectorAll('.install-edit').forEach(b=>b.addEventListener('click',()=>{if(!editModal||!editForm)return;const official=b.dataset.official==='1',domainInput=editForm.querySelector('[name="domain"]'),help=document.getElementById('installationEditHelp');editForm.installation_id.value=b.dataset.id||'';editForm.label.value=b.dataset.label||'';editForm.domain.value=b.dataset.domain||'';if(domainInput){domainInput.readOnly=official;domainInput.classList.toggle('is-readonly',official)}if(help)help.textContent=official?'Puedes cambiar libremente el nombre / etiqueta del sitio principal. El dominio oficial se administra automáticamente y no puede modificarse desde aquí.':'La etiqueta es solo para identificar el sitio dentro de ZYNKO. El dominio es el que autoriza técnicamente el widget.';window.ZynkoModal?.open('#installationEditModal')}));if(editForm)editForm.addEventListener('submit',async e=>{e.preventDefault();try{await post(new FormData(editForm));showNotify('success','Sitio actualizado','El nombre / etiqueta del sitio quedó actualizado correctamente.');setTimeout(()=>location.reload(),450)}catch(x){showNotify('error','No se pudo actualizar',x.message)}});document.querySelectorAll('.install-toggle').forEach(b=>b.onclick=async()=>{let f=new FormData();f.append('action','webchat_installation_toggle');f.append('installation_id',b.dataset.id);try{await post(f);location.reload()}catch(x){showNotify('error','Error',x.message)}});document.querySelectorAll('.install-delete').forEach(b=>b.onclick=async()=>{const ask=await Swal.fire({title:'Desautorizar sitio',text:'El chat dejará de funcionar inmediatamente en este dominio.',icon:'warning',showCancelButton:true,confirmButtonText:'Sí, desautorizar',cancelButtonText:'Cancelar',allowOutsideClick:false});if(!ask.isConfirmed)return;let f=new FormData();f.append('action','webchat_installation_delete');f.append('installation_id',b.dataset.id);try{await post(f);location.reload()}catch(x){showNotify('error','Error',x.message)}})});</script>
